class Solution {
public:
    long long minHeightDiff(vector<long long>& A, long long B) {
        vector<long long> a = A; sort(a.begin(), a.end()); int n = a.size();
        long long best = a[n - 1] - a[0];
        for (int i = 0; i + 1 < n; i++) {
            long long hi = max(a[i] + B, a[n - 1] - B), lo = min(a[0] + B, a[i + 1] - B);
            best = min(best, hi - lo);
        }
        return best;
    }
};

